   &lt;td&gt;AWS::SageMaker::InferenceComponent&lt;/td&gt; 
  &lt;/tr&gt;
  &lt;tr&gt;
   &lt;td&gt;AWS::Bedrock::DataAutomationProject&lt;/td&gt; 
